interface Logger { log(msg: string): void }
class NoOpLogger implements Logger { log(msg: string) { /* no op */ } }
function doAction(logger?: Logger) {
  const active = logger ?? new NoOpLogger();
  active.log('start');
  // ...
}

interface PaymentProcessor { process(amount: number): boolean }
class NullProcessor implements PaymentProcessor { process() { return false } }
const processors: Record<string, PaymentProcessor|undefined> = {}
function getProcessor(type: string) {
  return processors[type] ?? new NullProcessor();
}
function bill(type: string, amount: number) {
  const p = getProcessor(type);
  p.process(amount);
}

