interface Notifier { notify(payload: any): void }
class NoOpNotifier implements Notifier { notify() {} }
class EmailServiceA {
  constructor(private notifier?: Notifier) {
    this.notifier = notifier ?? new NoOpNotifier();
  }
  send(payload: any) { this.notifier.notify(payload); }
}

